B=[
('الْغُرَابُ يَطْلُبُ الصَّدَاقَةَ','Karga dostluk istiyor',[
('«فَلَمَّا رَأَى الْغُرَابُ صُنْعَ الْجُرَذِ، رَغِبَ فِي مُصَادَقَتِهِ.»','“Karga farenin yaptığını görünce onunla dost olmayı istedi.”'),
('«فَنَادَاهُ: يَا زِيرَكُ! قَالَ الْجُرَذُ: مَنْ أَنْتَ؟ قَالَ: أَنَا الْغُرَابُ.»','“Ona seslendi: Ey Zîrek! Fare dedi ki: Sen kimsin? Dedi ki: Ben kargayım.”'),
('«رَأَيْتُ وَفَاءَكَ لِخَلِيلَتِكَ، فَجِئْتُ لِأَطْلُبَ مَوَدَّتَكَ.»','“Dostuna olan vefanı gördüm ve sevgini istemeye geldim.”'),
('«قَالَ الْجُرَذُ: لَيْسَ بَيْنِي وَبَيْنَكَ تَوَاصُلٌ؛ إِنَّمَا أَنَا طَعَامُكَ وَأَنْتَ آكِلِي.»','“Fare dedi ki: Seninle benim aramda bağ yoktur; ben senin yemeğinim, sen de beni yiyensin.”'),
('«وَالْعَاقِلُ يَنْبَغِي لَهُ أَلَّا يَطْلُبَ مَا لَا يَجِدُ إِلَيْهِ سَبِيلًا.»','“Akıllı kişinin, yolunu bulamayacağı şeyi istememesi gerekir.”'),
('«قَالَ الْغُرَابُ: إِنَّ أَكْلِي إِيَّاكَ لَا يُغْنِي عَنِّي شَيْئًا، وَإِنَّ بَقَاءَكَ وَمَوَدَّتَكَ آنَسُ لِي.»','“Karga dedi ki: Seni yemem bana bir şey kazandırmaz; senin hayatta kalman ve dostluğun bana daha çok huzur verir.”'),
('«وَلَيْسَ مِنَ الْإِنْصَافِ أَنْ تَرُدَّنِي وَقَدْ جِئْتُكَ رَاغِبًا.»','“Sana istekle gelmişken beni geri çevirmen insaf değildir.”')]),
('الْعَدَاوَةُ وَالْعَهْدُ','Düşmanlık ve ahit',[
('«قَالَ الْجُرَذُ: إِنَّ أَشَدَّ الْعَدَاوَةِ عَدَاوَةُ الْجَوْهَرِ، كَعَدَاوَةِ الْمَاءِ وَالنَّارِ.»','“Fare dedi ki: Düşmanlığın en şiddetlisi tabiattan gelen düşmanlıktır; su ile ateşin düşmanlığı gibi.”'),
('«وَالْمَاءُ وَإِنْ سُخِّنَ حَتَّى صَارَ حَارًّا، إِذَا صُبَّ عَلَى النَّارِ أَطْفَأَهَا.»','“Su ısıtılıp sıcak olsa bile ateşe dökülünce onu söndürür.”'),
('«قَالَ الْغُرَابُ: قَدْ فَهِمْتُ، وَأَنْتَ خَلِيقٌ أَنْ تَأْخُذَ بِالْحَزْمِ.»','“Karga dedi ki: Anladım; sen ihtiyatlı davranmaya layıksın.”'),
('«وَلَكِنِّي لَا أَبْرَحُ بَابَكَ، وَلَا أَذُوقُ طَعَامًا حَتَّى تُؤَاخِيَنِي.»','“Ama sen benimle kardeş olana kadar kapından ayrılmam ve yemek tatmam.”'),
('«قَالَ الْجُرَذُ: قَدْ قَبِلْتُ إِخَاءَكَ؛ فَإِنِّي لَمْ أَرُدَّ أَحَدًا عَنْ حَاجَةٍ قَطُّ.»','“Fare dedi ki: Kardeşliğini kabul ettim; çünkü hiç kimseyi ihtiyacından geri çevirmedim.”'),
('«ثُمَّ خَرَجَ مِنْ جُحْرِهِ، فَوَقَفَ عِنْدَ الْبَابِ.»','“Sonra deliğinden çıktı ve kapının önünde durdu.”'),
('«فَقَالَ الْغُرَابُ: مَا يَمْنَعُكَ مِنَ الْخُرُوجِ إِلَيَّ؟ أَلَكَ فِي نَفْسِكَ مِنِّي رِيبَةٌ؟»','“Karga dedi ki: Yanıma çıkmana ne engel? İçinde benden bir şüphe mi var?”'),
('«قَالَ: إِنَّ لَكَ أَصْحَابًا جَوْهَرُهُمْ كَجَوْهَرِكَ، وَلَيْسَ رَأْيُهُمْ فِيَّ كَرَأْيِكَ.»','“Dedi ki: Senin tabiatları seninki gibi olan arkadaşların var; onların bana dair görüşü seninki gibi değil.”'),
('«فَعَاهَدَهُ الْغُرَابُ أَنْ يَحْفَظَهُ، فَخَرَجَ الْجُرَذُ وَتَصَافَيَا، وَأَنِسَ كُلٌّ بِصَاحِبِهِ.»','“Karga onu koruyacağına dair ahit verdi; fare çıktı, kalpten dost oldular ve her biri arkadaşıyla ünsiyet buldu.”')]),
('إِلَى الْعَيْنِ','Pınara doğru',[
('«فَلَبِثَا عَلَى ذَلِكَ أَيَّامًا، ثُمَّ قَالَ الْغُرَابُ: إِنَّ جُحْرَكَ قَرِيبٌ مِنْ طَرِيقِ النَّاسِ.»','“Bir süre böyle kaldılar; sonra karga dedi ki: Senin deliğin insanların yoluna yakın.”'),
('«وَأَخَافُ أَنْ يَرْمِيَكَ بَعْضُ الصِّبْيَانِ بِحَجَرٍ.»','“Bazı çocukların sana taş atmasından korkuyorum.”'),
('«وَلِي مَكَانٌ فِي عُزْلَةٍ، وَلِي فِيهِ صَدِيقٌ مِنَ السَّلَاحِفِ، وَهُوَ مَخْصِبٌ كَثِيرُ السَّمَكِ.»','“Benim ıssız bir yerde bir mekânım var; orada kaplumbağalardan bir dostum var; bolluk içinde, balığı çok bir yer.”'),
('«فَإِنْ رَأَيْتَ أَنْ تَنْطَلِقَ مَعِي إِلَيْهِ فَعِشْنَا هُنَاكَ آمِنَيْنِ.»','“Benimle oraya gelmeyi uygun görürsen orada güven içinde yaşarız.”'),
('«قَالَ الْجُرَذُ: مَا شَيْءٌ أَحَبَّ إِلَيَّ مِنْ ذَلِكَ؛ فَإِنَّ لِي أَخْبَارًا وَقَصَصًا أَقُصُّهَا عَلَيْكَ.»','“Fare dedi ki: Bundan daha sevimli bir şey yok; benim sana anlatacağım haberlerim ve hikâyelerim var.”'),
('«فَأَخَذَ الْغُرَابُ بِذَنَبِ الْجُرَذِ، وَطَارَ بِهِ حَتَّى بَلَغَ الْعَيْنَ.»','“Karga farenin kuyruğundan tuttu ve onunla uçarak pınara vardı.”'),
('«فَلَمَّا رَأَتِ السُّلَحْفَاةُ الْغُرَابَ وَمَعَهُ جُرَذٌ ذُعِرَتْ، وَغَاصَتْ فِي الْمَاءِ.»','“Kaplumbağa kargayı ve yanında bir fareyi görünce korktu ve suya daldı.”'),
('«فَنَادَاهَا الْغُرَابُ، فَخَرَجَتْ وَسَأَلَتْهُ عَنْ صَاحِبِهِ، فَأَخْبَرَهَا بِقِصَّتِهِ.»','“Karga ona seslendi; o çıktı ve ona arkadaşını sordu; karga da ona hikâyesini anlattı.”')]),
('قِصَّةُ الْجُرَذِ','Farenin hikâyesi',[
('«قَالَ الْجُرَذُ: كُنْتُ أَسْكُنُ بَيْتَ رَجُلٍ نَاسِكٍ، وَكَانَ يَضَعُ طَعَامَهُ فِي سَلَّةٍ مُعَلَّقَةٍ.»','“Fare dedi ki: Zâhid bir adamın evinde otururdum; o yemeğini asılı bir sepete koyardı.”'),
('«فَكُنْتُ أَثِبُ إِلَى السَّلَّةِ، فَآكُلُ وَأُطْعِمُ أَصْحَابِي الْجِرْذَانَ.»','“Ben sepete sıçrar, yer ve fare arkadaşlarımı doyururdum.”'),
('«فَجَاءَهُ ضَيْفٌ ذَاتَ لَيْلَةٍ، فَرَأَى السَّلَّةَ تَهْتَزُّ، فَقَالَ: لَا بُدَّ أَنَّ هُنَا مَالًا يُقَوِّي صَاحِبَهُ.»','“Bir gece ona bir misafir geldi; sepetin sallandığını gördü ve dedi ki: Burada mutlaka sahibini güçlendiren bir mal var.”'),
('«فَحَفَرَ جُحْرِي، فَوَجَدَ دَنَانِيرَ كُنْتُ أَجْمَعُهَا، فَأَخَذَهَا.»','“Deliğimi kazdı, biriktirdiğim altın dinarları buldu ve aldı.”'),
('«فَذَهَبَتْ قُوَّتِي، وَلَمْ أَقْدِرْ عَلَى الْوُثُوبِ، وَتَرَكَنِي أَصْحَابِي.»','“Gücüm gitti, sıçrayamaz oldum ve arkadaşlarım beni terk etti.”'),
('«فَقُلْتُ: مَا الْإِخْوَانُ وَلَا الْأَعْوَانُ إِلَّا بِالْمَالِ.»','“Dedim ki: Dostlar da yardımcılar da ancak mal iledir.”'),
('«ثُمَّ عَلِمْتُ أَنَّ الْقَنَاعَةَ خَيْرٌ مِنَ الْمَالِ، فَتَرَكْتُ ذَلِكَ الْبَيْتَ، وَرَضِيتُ بِالْقَلِيلِ.»','“Sonra kanaatin maldan hayırlı olduğunu öğrendim; o evi bıraktım ve aza razı oldum.”')]),
('الظَّبْيُ','Ceylan',[
('«وَبَيْنَمَا هُمْ ذَاتَ يَوْمٍ عِنْدَ الْعَيْنِ، إِذْ أَقْبَلَ ظَبْيٌ يَسْعَى خَائِفًا.»','“Bir gün onlar pınarın yanındayken korkuyla koşan bir ceylan geldi.”'),
('«فَذُعِرَتْ مِنْهُ السُّلَحْفَاةُ، وَدَخَلَ الْجُرَذُ جُحْرَهُ، وَطَارَ الْغُرَابُ فَوْقَ شَجَرَةٍ.»','“Kaplumbağa ondan korktu, fare deliğine girdi, karga da bir ağacın üstüne uçtu.”'),
('«ثُمَّ نَظَرَ الْغُرَابُ فَلَمْ يَرَ أَحَدًا يَطْلُبُ الظَّبْيَ.»','“Sonra karga baktı ve ceylanı kovalayan kimseyi görmedi.”'),
('«فَقَالَتِ السُّلَحْفَاةُ لِلظَّبْيِ: اشْرَبْ إِنْ كَانَ بِكَ عَطَشٌ، وَلَا تَخَفْ، فَإِنَّهُ لَا خَوْفَ عَلَيْكَ.»','“Kaplumbağa ceylana dedi ki: Susadıysan iç ve korkma; sana bir korku yok.”'),
('«قَالَ الظَّبْيُ: كُنْتُ بِأَرْضِ قَوْمٍ، فَطَرَدَنِي الرُّمَاةُ، فَجِئْتُ هَارِبًا.»','“Ceylan dedi ki: Bir kavmin topraklarındaydım; okçular beni kovaladı ve kaçarak geldim.”'),
('«قَالَتِ السُّلَحْفَاةُ: أَقِمْ مَعَنَا، فَإِنَّ الْمَكَانَ خَصِيبٌ، وَنَحْنُ لَكَ إِخْوَانٌ.»','“Kaplumbağa dedi ki: Bizimle kal; çünkü yer bereketlidir ve biz sana kardeşiz.”'),
('«فَأَقَامَ الظَّبْيُ مَعَهُمْ، وَكَانُوا يَجْتَمِعُونَ كُلَّ يَوْمٍ يَتَحَدَّثُونَ.»','“Ceylan onlarla kaldı; her gün toplanıp sohbet ederlerdi.”')]),
('الظَّبْيُ فِي الشَّرَكِ','Tuzaktaki ceylan',[
('«فَغَابَ الظَّبْيُ يَوْمًا عَنْ مَوْعِدِهِ، فَقَلِقَ أَصْحَابُهُ.»','“Bir gün ceylan buluşma vaktinde gelmedi; arkadaşları endişelendi.”'),
('«فَقَالُوا لِلْغُرَابِ: طِرْ فَانْظُرْ هَلْ تَرَى مِنْهُ شَيْئًا.»','“Kargaya dediler ki: Uç ve bak, ondan bir iz görüyor musun.”'),
('«فَحَلَّقَ الْغُرَابُ، فَإِذَا الظَّبْيُ فِي حِبَالَةِ صَيَّادٍ.»','“Karga havalandı; bir de ne görsün, ceylan bir avcının tuzağında.”'),
('«فَرَجَعَ مُسْرِعًا فَأَخْبَرَهُمَا.»','“Hızla döndü ve ikisine haber verdi.”'),
('«فَقَالَتِ السُّلَحْفَاةُ وَالْغُرَابُ لِلْجُرَذِ: هَذَا أَمْرٌ لَا يُرْجَى فِيهِ غَيْرُكَ، فَأَغِثْ أَخَاكَ.»','“Kaplumbağa ve karga fareye dediler ki: Bu, senden başkasından umut edilmeyecek bir iş; kardeşine yetiş.”'),
('«فَحَمَلَهُ الْغُرَابُ إِلَى الظَّبْيِ، فَجَعَلَ يَقْرِضُ الْحَبَائِلَ.»','“Karga onu ceylana taşıdı; fare ipleri kemirmeye başladı.”'),
('«وَجَاءَتِ السُّلَحْفَاةُ تَمْشِي بِبُطْءٍ حَتَّى وَصَلَتْ إِلَيْهِمْ.»','“Kaplumbağa da yavaş yavaş yürüyerek onlara ulaştı.”')]),
('السُّلَحْفَاةُ الْأَسِيرَةُ','Esir kaplumbağa',[
('«فَقَالَ الظَّبْيُ لِلسُّلَحْفَاةِ: مَا جَاءَ بِكِ؟ إِنْ جَاءَ الصَّيَّادُ نَجَوْنَا نَحْنُ، وَأَنْتِ بَطِيئَةٌ.»','“Ceylan kaplumbağaya dedi ki: Seni ne getirdi? Avcı gelirse biz kurtuluruz, sen ise yavaşsın.”'),
('«قَالَتْ: كَيْفَ أَصْبِرُ عَنْ إِخْوَانِي؟ لَا خَيْرَ فِي الْعَيْشِ بَعْدَ فِرَاقِ الْأَحِبَّةِ.»','“Dedi ki: Kardeşlerimden nasıl uzak durayım? Sevdiklerden ayrıldıktan sonra yaşamakta hayır yoktur.”'),
('«فَلَمْ يَفْرُغِ الْجُرَذُ مِنْ قَطْعِ الْحِبَالَةِ حَتَّى أَقْبَلَ الصَّيَّادُ.»','“Fare ipleri kesmeyi bitirir bitirmez avcı geldi.”'),
('«فَعَدَا الظَّبْيُ، وَطَارَ الْغُرَابُ، وَدَخَلَ الْجُرَذُ بَعْضَ الْأَجْحَارِ.»','“Ceylan koştu, karga uçtu, fare de deliklerden birine girdi.”'),
('«وَلَمْ يَبْقَ إِلَّا السُّلَحْفَاةُ، فَأَخَذَهَا الصَّيَّادُ وَرَبَطَهَا.»','“Kaplumbağadan başkası kalmadı; avcı onu aldı ve bağladı.”'),
('«فَحَزِنَ أَصْحَابُهَا حُزْنًا شَدِيدًا.»','“Arkadaşları çok derin bir hüzünle üzüldüler.”'),
('«وَقَالَ الْجُرَذُ: مَا أَرَانِي أَجُوزُ عَقَبَةً إِلَّا وَقَعْتُ فِي أَشَدَّ مِنْهَا.»','“Fare dedi ki: Görüyorum ki bir geçidi aşar aşmaz ondan daha zoruna düşüyorum.”')]),
('الْخَلَاصُ','Kurtuluş',[
('«ثُمَّ قَالَ الْجُرَذُ: لِي حِيلَةٌ. يَا ظَبْيُ، اذْهَبْ فَاسْقُطْ عَلَى طَرِيقِ الصَّيَّادِ كَأَنَّكَ مَيِّتٌ.»','“Sonra fare dedi ki: Benim bir hilem var. Ey ceylan, git ve avcının yoluna ölü gibi düş.”'),
('«وَيَقَعُ الْغُرَابُ عَلَيْكَ كَأَنَّهُ يَأْكُلُ مِنْكَ.»','“Karga da sanki senden yiyormuş gibi üstüne konsun.”'),
('«فَإِذَا رَآكَ الصَّيَّادُ وَضَعَ السُّلَحْفَاةَ وَأَقْبَلَ نَحْوَكَ، فَأَقْرِضُ أَنَا حِبَالَهَا.»','“Avcı seni görünce kaplumbağayı bırakıp sana yönelir; ben de onun iplerini kemiririm.”'),
('«فَفَعَلَا، فَلَمَّا رَآهُ الصَّيَّادُ طَمِعَ فِيهِ، وَوَضَعَ الْجِرَابَ الَّذِي فِيهِ السُّلَحْفَاةُ.»','“İkisi öyle yaptı; avcı ceylanı görünce ona tamah etti ve içinde kaplumbağa bulunan torbayı yere koydu.”'),
('«فَلَمَّا دَنَا مِنَ الظَّبْيِ قَامَ يَعْدُو، وَالصَّيَّادُ يَتْبَعُهُ حَتَّى أَبْعَدَهُ.»','“Ceylana yaklaşınca ceylan kalkıp koştu; avcı da onu uzaklaşana kadar kovaladı.”'),
('«وَقَرَضَ الْجُرَذُ الْحِبَالَ، فَنَجَتِ السُّلَحْفَاةُ.»','“Fare ipleri kemirdi ve kaplumbağa kurtuldu.”'),
('«فَرَجَعَ الصَّيَّادُ فَلَمْ يَجِدْ شَيْئًا، فَتَحَيَّرَ وَقَالَ: مَا هَذِهِ إِلَّا أَرْضُ جِنٍّ!»','“Avcı döndü ve hiçbir şey bulamadı; şaşırdı ve dedi ki: Burası cin diyarından başka bir şey değil!”'),
('«فَانْصَرَفَ خَائِفًا، وَاجْتَمَعَ الْأَصْحَابُ الْأَرْبَعَةُ سَالِمِينَ.»','“Korkarak döndü gitti; dört arkadaş da sağ salim bir araya geldi.”')]),
('الْعِبْرَةُ','İbret',[
('قَالَ بَيْدَبَا: «فَهَذِهِ الدَّوَابُّ، مَعَ صِغَرِهَا وَضَعْفِهَا، نَجَتْ مِنْ مَهَالِكَ كَثِيرَةٍ بِالْمَوَدَّةِ وَالتَّعَاوُنِ.»','Beydebâ dedi ki: “İşte bu hayvanlar, küçüklüklerine ve zayıflıklarına rağmen, sevgi ve yardımlaşmayla birçok tehlikeden kurtuldular.”'),
('«فَالْإِنْسَانُ الَّذِي أُعْطِيَ الْعَقْلَ وَالْفَهْمَ أَحَقُّ بِذَلِكَ.»','“Akıl ve anlayış verilen insan buna daha layıktır.”'),
('«وَالصَّدِيقُ الصَّادِقُ يُعْرَفُ عِنْدَ الشِّدَّةِ.»','“Sadık dost darlıkta tanınır.”'),
('«وَمَنْ لَا صَدِيقَ لَهُ، فَهُوَ كَالْغَرِيبِ وَإِنْ كَانَ فِي بَلَدِهِ.»','“Dostu olmayan, kendi memleketinde olsa bile garip gibidir.”'),
('فَقَالَ الْمَلِكُ: «صَدَقْتَ أَيُّهَا الْحَكِيمُ.»','Kral dedi ki: “Doğru söyledin ey hakîm.”'),
('«سَأَجْعَلُ هَذَا الْمَثَلَ أَمَامَ عَيْنِي كُلَّ يَوْمٍ.»','“Bu misali her gün gözümün önünde tutacağım.”')]),
]
